    la=np.deg2rad(np.asarray(la,dtype=float)); lo=np.deg2rad(np.asarray(lo,dtype=float))
    return np.stack([np.cos(lo)*np.cos(la), np.sin(lo)*np.cos(la), np.sin(la)], axis=-1)

def inside_mesh(lon, lat, plat, plon):
    """Exact spherical containment: is each (plat, plon) inside any cell of the mesh?"""
    P = xyz_deg(lat, lon)
    v0=P[:-1,:-1]; v1=P[:-1,1:]; v2=P[1:,1:]; v3=P[1:,:-1]
    def tri(a,b,c,p):
        s1=np.einsum('...i,i->...',np.cross(a,b),p); s2=np.einsum('...i,i->...',np.cross(b,c),p); s3=np.einsum('...i,i->...',np.cross(c,a),p)
        return ((s1>=0)&(s2>=0)&(s3>=0))|((s1<=0)&(s2<=0)&(s3<=0))
    out=[]
    for la,lo in zip(np.atleast_1d(plat), np.atleast_1d(plon)):
        p=xyz_deg(la,lo)
