def _in_unit_square(xsi: np.ndarray, eta: np.ndarray) -> np.ndarray:
    """Check whether relative coordinates describe a point inside its cell.

    Points whose coordinates are not defined (where the inversion of the bilinear map of the
    cell has no solution) are not inside it.
    """
    return (xsi >= 0.0) & (xsi <= 1.0) & (eta >= 0.0) & (eta <= 1.0)

